check_cable: inputSchema  parameters: -hd-627-7-n. +hd-627-7-n, bs-7211-2012, as-nzs-5000-2-2006, ul-62-spt, din-vde-0815, din-vde-0250-502, din-vde-0250-602, din-vde-0250-806, din-vde-0250-812, din-vde-0250-814, sans-1507-4-2022, as-nzs-5000-3-2003.
design_cable: inputSchema  parameters: -grade} +grade, ecc} -grade; +grade (ecc true: a flat twin with its bare ECC);
drum_fit: inputSchema  parameters: +input.barrel_od input.barrel_od description: A bundle's lay-up diameter, mm, for the barrel check where it is not od (a triplex or three single cores laid up: drum.ts barrelBasis); the capacity still winds on od. Default od.
find_equivalents: inputSchema  parameters: +SANS1507-4,
iec60287_rating: description, inputSchema  +Also ducts in a concrete bank (IEC 60287-2-1 4.2.7.4), a sand-filled or an unfilled trough (4.2.6), identical circuits side by side (4.2.3.3.1) and a heat source crossing the route (IEC 60287-3-3:2007, the derating factor DF). -armour, duct banks, troughs, +armour (no strip thickness held), -circuits, crossings. +circuits in free air (IEC 60287-2-2), and the cyclic and emergency ratings with a bank, a trough, a group or a crossing. -maximum)}; +maximum), bank?: {xMm, yMm, rho?} (laying duct: the ducts in a concrete bank, its sides, mm, depthM to its centre; rho default 1.0, IEC 60287-2-1 Tabl  parameters: -maximum)}; +maximum), bank?: {xMm, yMm, rho?} (laying duct: the ducts in a concrete bank, its sides, mm, depthM to its centre; rho default 1.0, IEC 60287-2-1 Table 1), trough?: "sand" (laying buried: the sand at 2.5 K·m/W, 4.2.6.1) | {perimeterM} (laying air: an unfilled trough flush with the ground, 4.2.6.2), circuits?: {count, spacingMm} (buried or duct: identical circuits side by side, centres apart, 4.2.3.3.1), crossing?: {wattsPerM, depthM, angleDeg?} (buried or duct: a crossing heat source, IEC 60287-3-3; angle default 90)};

enhance_video_prompt: inputSchema  parameters: -720p and +720p, +and 4k -mode (no 2K/4K). +mode. -only +also -text/image and +text/image, -Omni; +Omni and standard Seedance 2.0;
generate_video: inputSchema  parameters: -720p and +720p, +and 4k -mode (no 2K/4K). +mode. -only +also -text/image and +text/image, -Omni; +Omni and standard Seedance 2.0; -720p and +720p, +and 4k -mode (no 2K/4K). +mode. -only +also -text/image and +text/image, -Omni; +Omni and standard Seedance 2.0;
quote_video: inputSchema  parameters: -720p and +720p, +and 4k -mode (no 2K/4K). +mode. -only +also -text/image and +text/image, -Omni; +Omni and standard Seedance 2.0;
